import {decodeAccountSnapshot,encodeAccountSnapshot,makeAccountSnapshot} from './account-data.js?v=0.61';
export const FIREBASE_SDK_VERSION='12.19.0';
export function parseAccountConfig(value){
 if(!value||value.schemaVersion!==1)throw Error('アカウント設定の形式が正しくありません');if(value.firebase===null)return null;
 const f=value.firebase,project=f?.projectId;if(!f||typeof project!=='string'||!/^[a-z][a-z0-9-]{4,28}[a-z0-9]$/.test(project)||typeof f.apiKey!=='string'||!/^AIza[A-Za-z0-9_-]{20,100}$/.test(f.apiKey)||typeof f.appId!=='string'||!/^1:\d+:web:[a-zA-Z0-9]+$/.test(f.appId)||f.authDomain!==project+'.firebaseapp.com')throw Error('FirebaseのWeb用公開設定を確認してください');
 return {apiKey:f.apiKey,authDomain:f.authDomain,projectId:project,appId:f.appId};
}
const googleUser=u=>u&&typeof u.uid==='string'&&u.uid.length>0&&u.uid.length<=128&&u.providerData?.some(p=>p.providerId==='google.com')?{uid:u.uid,name:String(u.displayName||'Googleユーザー').slice(0,120),email:String(u.email||'').slice(0,254)}:null;
export function accountError(error){const code=String(error?.code||'');return ({'auth/popup-blocked':'ログイン画面を開けませんでした。SafariやChromeでアプリを開き、ポップアップを許可して再度お試しください。','auth/popup-closed-by-user':'ログイン画面を閉じました。','auth/cancelled-popup-request':'開いているログイン画面で操作を続けてください。','auth/unauthorized-domain':'Firebaseの「承認済みドメイン」に、このアプリのドメインを追加してください。','auth/operation-not-allowed':'Firebase AuthenticationでGoogleを有効にしてください。','auth/web-storage-unsupported':'このブラウザではログインを保存できません。SafariやChromeでお試しください。','auth/network-request-failed':'通信できませんでした。接続を確認して再度お試しください。','permission-denied':'クラウド保存を利用できません。Cloud Firestoreの作成と、このアプリ用のセキュリティルールを確認してください。','unavailable':'クラウドに接続できません。通信が戻ってから再読込してください。','cloud/conflict':'別の端末で保存が更新されています。再読込して内容を確認・取り込みしてから保存してください。','cloud/session-changed':'アカウントが切り替わりました。現在のアカウントでやり直してください。','cloud/timeout':'通信の完了を確認できませんでした。再読込して保存状態を確認してください。','auth/account-exists-with-different-credential':'別のログイン方法で登録されたアカウントです。Firebaseの登録状況を確認してください。','auth/operation-not-supported-in-this-environment':'このブラウザではGoogleログインを開けません。SafariまたはChromeでアプリを開いてください。','auth/invalid-api-key':'FirebaseのWeb用公開設定を確認してください。','auth/configuration-not-found':'Firebaseコンソールで「Authentication → 始める」を選び、「Google」を有効にしてください。','resource-exhausted':'Firebaseの無料枠を超えたか、リクエストが集中しています。時間をおいて再度お試しください。','auth/invalid-user-token':'ログインが無効になりました。ログアウトして入り直してください。','auth/user-disabled':'このGoogleログインは無効になっています。'})[code]||'アカウント処理を完了できませんでした。再読込してお試しください。';}
export async function createFirebaseAdapter(config,{loadModule=url=>import(url)}={}){
 const base='https://www.gstatic.com/firebasejs/'+FIREBASE_SDK_VERSION+'/';const [appSDK,authSDK,dbSDK]=await Promise.all(['firebase-app.js','firebase-auth.js','firebase-firestore.js'].map(f=>loadModule(base+f)));
 const app=appSDK.initializeApp(config,'duema-deck-lab'),auth=authSDK.getAuth(app),db=dbSDK.getFirestore(app);auth.languageCode='ja';const provider=new authSDK.GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});
 const ref=uid=>{if(!auth.currentUser||auth.currentUser.uid!==uid||!googleUser(auth.currentUser))throw Object.assign(Error(),{code:'cloud/session-changed'});return dbSDK.doc(db,'deckLabAccounts',uid);};
 const row=s=>s.exists()?{payload:s.data().payload,revision:s.data().revision,updatedAt:s.data().updatedAt?.toDate?.().toISOString()||null}:null;
 return {watch:cb=>authSDK.onAuthStateChanged(auth,u=>cb(googleUser(u))),signIn:()=>authSDK.signInWithPopup(auth,provider),signOut:()=>authSDK.signOut(auth),getIdToken:()=>{if(!googleUser(auth.currentUser))throw Error('ログインしてください');return auth.currentUser.getIdToken();},
  read:async uid=>row(await dbSDK.getDocFromServer(ref(uid))),
  write:async(uid,payload,expected)=>{const target=ref(uid);await dbSDK.runTransaction(db,async tx=>{ref(uid);const current=await tx.get(target),revision=current.exists()?current.data().revision:0;if(!Number.isSafeInteger(revision)||revision!==expected)throw Object.assign(Error(),{code:'cloud/conflict'});ref(uid);tx.set(target,{schemaVersion:1,payload,revision:revision+1,updatedAt:dbSDK.serverTimestamp()});});return {payload,revision:expected+1,updatedAt:null};},
 };
}
export function createAccountClient({registry,onChange=()=>{},fetchConfig=async()=>{const r=await fetch('account-config.json?v=0.44',{cache:'no-store'});if(!r.ok)throw Error('config');return r.json();},createAdapter=createFirebaseAdapter,timeoutMs=15000}={}){
 let adapter=null,stop=null,epoch=0,pending=null,initial=null;const state={phase:'idle',user:null,cloud:null,loaded:false,busy:null,error:null};
 const emit=()=>onChange(structuredClone(state));const error=e=>{state.error=accountError(e);};
 async function bounded(promise){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Object.assign(Error(),{code:'cloud/timeout'})),timeoutMs);})]);}finally{clearTimeout(timer);}}
 function unpack(row){if(!row)return null;if(!Number.isSafeInteger(row.revision)||row.revision<1)throw Error('revision');return {snapshot:decodeAccountSnapshot(row.payload,registry),revision:row.revision,updatedAt:row.updatedAt};}
 async function refresh(){if(!adapter||!state.user||state.busy)return;const version=epoch,who=state.user.uid;state.busy='load';state.error=null;emit();try{const row=await bounded(adapter.read(who));if(epoch!==version)return;state.cloud=unpack(row);state.loaded=true;}catch(e){if(epoch===version){state.loaded=false;error(e);}}finally{if(epoch===version){state.busy=null;emit();}}}
 async function authChanged(user){epoch++;pending=null;state.user=user;state.cloud=null;state.loaded=false;state.busy=null;state.error=null;state.phase=user?'signed-in':'signed-out';emit();if(user)await refresh();}
 async function init(){if(initial)return initial;initial=(async()=>{state.phase='loading';emit();try{const config=parseAccountConfig(await bounded(fetchConfig()));if(!config){state.phase='unconfigured';emit();return;}adapter=await bounded(createAdapter(config));state.phase='loading';stop=adapter.watch(authChanged);}catch(e){state.phase='error';error(e);emit();}})();return initial;}
 async function signIn(){if(!adapter||state.phase!=='signed-out'||state.busy)return;const version=epoch;state.busy='login';state.error=null;emit();try{await adapter.signIn();}catch(e){if(epoch===version){error(e);state.busy=null;emit();}}}
 async function signOut(){if(!adapter||!state.user||state.busy)return;const version=epoch;state.busy='logout';state.error=null;emit();try{await bounded(adapter.signOut());if(epoch===version)await authChanged(null);}catch(e){if(epoch===version){state.busy=null;error(e);emit();}}}
 function prepareSave(saved){if(!state.user||!state.loaded||state.busy)throw Error('ログインとクラウドの読込を完了してください');const snapshot=makeAccountSnapshot(saved,registry),payload=encodeAccountSnapshot(snapshot);if(!snapshot.decks.length&&!snapshot.friends.length)throw Error('保存するデッキがありません');pending={epoch,uid:state.user.uid,payload,snapshot,revision:state.cloud?.revision||0};return {uid:pending.uid,snapshot:structuredClone(snapshot),cloud:structuredClone(state.cloud)};}
 async function save(){if(!pending||state.busy||pending.epoch!==epoch||pending.uid!==state.user?.uid)throw Error('保存内容をもう一度確認してください');const request=pending;pending=null;state.busy='save';state.error=null;emit();try{const row=await bounded(adapter.write(request.uid,request.payload,request.revision));if(epoch!==request.epoch)return false;state.cloud=unpack(row);state.loaded=true;return true;}catch(e){if(epoch===request.epoch){error(e);state.loaded=false;}return false;}finally{if(epoch===request.epoch){state.busy=null;emit();}}}
 return {init,refresh,signIn,signOut,prepareSave,save,async getIdToken(){if(!state.user||!adapter)throw Error('Googleアカウントでログインしてください。');const who=state.user.uid,token=await adapter.getIdToken();if(state.user?.uid!==who)throw Error('アカウントが切り替わりました。');return token;},getState:()=>structuredClone(state),getSnapshot(){if(!state.user||!state.loaded||state.busy||!state.cloud)throw Error('保存内容を読み込んでください');return {uid:state.user.uid,revision:state.cloud.revision,snapshot:structuredClone(state.cloud.snapshot)};},dispose(){epoch++;stop?.();pending=null;}};
}
